FIGS.journey = (el) => {
  const S = L.journey.steps;
  el.innerHTML = `<div class="ctl" id="jyC" style="margin-top:0"></div>
    <div style="display:grid;grid-template-columns:1fr 470px;gap:18px;margin-top:12px;height:580px">
      <div class="thread" id="jyT" style="font-size:18px"></div>
      <div class="trace" id="jyR" style="font-size:14.5px"></div></div>`;
  let cur = 4;
  const lab = (s, i) => ({ 'sign in': 'sign in', 'new conversation': 'new chat', 'message': `Kavita ${S.slice(0, i + 1).filter((x) => x.what === 'message').length}`, 'tries to approve her own request': 'self-approve', 'opens the inbox': 'Rohit: inbox', 'one tap: approve': 'Rohit: one tap' }[s.what] || s.what);
  const draw = () => {
    el.querySelector('#jyC').innerHTML = S.map((s, i) => `<button data-i="${i}" class="${i === cur ? 'on' : ''}">${lab(s, i)}</button>`).join('');
    el.querySelectorAll('#jyC button').forEach((b) => b.addEventListener('click', () => { cur = +b.dataset.i; draw(); }));
    const msgs = [];
    S.slice(0, cur + 1).forEach((s) => {
      if (s.what === 'message') {
        msgs.push(`<div class="msg u"><div class="who">Kavita</div>${esc(s.text)}</div>`);
        msgs.push(`<div class="msg ag" style="white-space:pre-line"><div class="who">Agent</div>${esc(cut2(s.reply, 470))}</div>`);
      } else if (s.what === 'one tap: approve') msgs.push(`<div class="msg ag"><div class="who">Agent, after Rohit's tap</div>${esc(cut(s.kavita_sees, 200))}</div>`);
    });
    const th = el.querySelector('#jyT');
    th.innerHTML = msgs.slice(-3).join('') || '<div class="small">Kavita signs in. Her token is the agent\'s identity.</div>';
    const s = S[cur];
    let r = `<div class="h">${s.who} · ${esc(s.what)}</div>`;
    if (s.trace) r += s.trace.map((t) => `<div class="l">${esc(cut(t, 150))}</div>`).join('');
    if (s.waiting) r += `<div class="l ok">waiting on ${s.waiting.approver} · ${s.waiting.doc_no} · ${s.waiting.status}</div>`;
    if (s.status) r += `<div class="l x">HTTP ${s.status} · ${esc(s.detail)}</div>`;
    if (s.items) r += s.items.map((it) => `<div class="l"><b>${it.doc_no}</b> ${esc(cut(it.summary, 90))} · ${it.rule}</div>`).join('') + (s.slack || []).map((m) => `<div class="l">Slack: ${esc(cut(m, 120))}</div>`).join('');
    if (s.bahi) r += `<div class="l ok">Bahi: ${esc(s.bahi.msg)}</div>`;
    if (s.what === 'sign in') r += `<div class="l">KJOSHI · PUR-EXEC · limit ₹2,50,000</div>`;
    if (s.what === 'new conversation') r += `<div class="l">acts as: ${L.journey.acts_as.acts_as} (${L.journey.acts_as.kind})</div>`;
    el.querySelector('#jyR').innerHTML = r;
  };
  return { step() { draw(); } };
};

